def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n >= 95:
        return 'D'
    my_prev = history[-1][0]
    opp_prev = history[-1][1]
    if opp_prev == 'C':
        if my_prev == 'D':
            return 'C' if rng.random() < 0.8 else 'D'
        return 'C'
    recent_opp = history[-10:]
    opp_def = sum(1 for _, o in recent_opp if o == 'D')
    if n >= 8:
        if opp_def >= 4:
            return 'D'
        if opp_def >= 2 and n >= 20:
            if rng.random() < 0.15:
                return 'C'
            return 'D'
    if n >= 4:
        if history[-2][1] == 'D' and history[-3][1] == 'D':
            return 'D'
        if history[-2][1] == 'D' and rng.random() < 0.25:
            return 'C'
    if n >= 20:
        total_def = sum(1 for _, o in history if o == 'D')
        if total_def * 10 > n * 6:
            return 'D'
    if rng.random() < 0.1:
        return 'C'
    return 'D'
